  else if(a.Stage==AdventureStage.Reward){for(int i=0;i<3;i++){float x=r.x+57+i*218;Icon(new Rect(x,r.y+282,210,271),8);Text(new Rect(x+15,r.y+300,180,57),AdventureRelics.Name(i),new GUIStyle(center){fontSize=18},true);Text(new Rect(x+20,r.y+370,170,108),AdventureRelics.Description(i),new GUIStyle(label){fontSize=14},true);GUI.enabled=!a.Relics.Owns(i);if(Button(new Rect(x+15,r.y+494,180,43),a.Relics.Owns(i)?AdventureProgress.T("보유 중","Owned","所持中"):AdventureProgress.T("선택","Choose","選ぶ"),true)&&a.ChooseRelic(i))Close();GUI.enabled=true;}}
  else if(a.Stage==AdventureStage.Camp){for(int i=0;i<2;i++){GUI.enabled=(a.State.sideDone&(1<<i))==0;if(Button(new Rect(r.x+125,r.y+477+i*68,510,50),i==0?AdventureProgress.T("달빛 약초 회수","Gather Moon Herbs","月光草を集める"):AdventureProgress.T("꿀날개 둥지 정화","Cleanse Honeywing Nest","蜂の巣を浄化"),true)&&a.AcceptSide(i))Close();GUI.enabled=true;}}
  else if(Button(new Rect(r.x+140,r.y+515,480,54),AdventureProgress.T("숲으로 돌아가기","Return to the forest","森に戻る"),true))Close();
 }
